#define _GNU_SOURCE
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include "stations.h"

#define N 413
#define SLOTS 1024
#define THREADS 4
#define HASH 0x9e3779b97f4a7c15ULL
typedef struct { uint64_t sum; uint32_t count; int16_t min, max; } Stats;
typedef struct { uint64_t key; int len, idx, ambiguous; } Station;
typedef struct { Stats stats[N]; const char *begin, *end; } Worker;
static Worker *workers;
static Station stations[N];
static Station *map[SLOTS];
static const char *data;
static size_t file_size;
static void init(void) {
    for(int i=0;i<N;i++) {
        const char *n=names[i]; int len=strlen(n);
        uint64_t key=0; memcpy(&key,n,len<8?len:8);
        stations[i]=(Station){.key=key,.len=len,.idx=i};
        unsigned slot=(key*HASH)>>(64-10);
        while(map[slot]) {
            if(map[slot]->key==key) {
                map[slot]->ambiguous=1; stations[i].ambiguous=1;
