static size_t file_size;
static void *work(void *arg) {
    Worker *w=arg;
    const char *p=w->begin, *end=w->end;
    while(p<end) {
        const char *name=p;
        unsigned len;
        __m128i v=_mm_loadu_si128((const __m128i*)p);
        uint64_t first=(uint64_t)_mm_cvtsi128_si64(v);
        unsigned mask=(unsigned)_mm_movemask_epi8(_mm_cmpeq_epi8(v,_mm_set1_epi8(';')));
        unsigned len;
        if(mask) len=__builtin_ctz(mask);
        else {
            __m128i v2=_mm_loadu_si128((const __m128i*)(p+16));
            unsigned mask2=(unsigned)_mm_movemask_epi8(_mm_cmpeq_epi8(v2,_mm_set1_epi8(';')));
            len=16+__builtin_ctz(mask2);
        }
        p+=len;
        uint64_t h;
        if(len<8) first &= (1ULL << (len*8))-1;
        h=(first&0x00ffffffffffffffULL) | ((uint64_t)len<<56);
        p++;
        int sign=1;
        if(*p=='-') { sign=-1; p++; }
        int t=*p++-'0';
        if(*p!='.') t=t*10+(*p++-'0');
        p++;
        t=t*10+(*p++-'0');
        t*=sign;
        p++; // newline
        unsigned idx=(h*0x3d7f8ec076a05f4fULL)>>51;
        Entry *s=w->slots;

        Entry *v=s+idx;
        if(!v->name) { v->name=name; v->len=len; v->min=v->max=t; }
        else { if(t<v->min) v->min=t; if(t>v->max) v->max=t; }
        v->sum+=t; v->count++;
    }
    return NULL;
}
