#define _GNU_SOURCE
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include "stations.h"

#define N 413
#define SLOTS 1024
#define THREADS 4
#define HASH 0x9e3779b97f4a7c15ULL
typedef struct { uint64_t sum; uint32_t count; int16_t min, max; } Stats;
typedef struct { uint64_t key; int len, idx, ambiguous; } Station;
typedef struct { Stats stats[N]; const char *begin, *end; } Worker;
static Worker *workers;
static Station stations[N];
static Station *map[SLOTS];
static const char *data;
static size_t file_size;
static void init(void) {
    for(int i=0;i<N;i++) {
        const char *n=names[i]; int len=strlen(n);
        uint64_t key=0; memcpy(&key,n,len<8?len:8);
        stations[i]=(Station){.key=key,.len=len,.idx=i};
        unsigned slot=(key*HASH)>>(64-10);
        while(map[slot]) {
            if(map[slot]->key==key) {
                map[slot]->ambiguous=1; stations[i].ambiguous=1;
            }
            slot=(slot+1)&(SLOTS-1);
        }
        map[slot]=&stations[i];
    }
}
static void *work(void *arg) {
    Worker *w=arg;
    const char *p=w->begin, *end=w->end;
    while(p<end) {
        uint64_t key; memcpy(&key,p,8);
        uint64_t x=key^0x3b3b3b3b3b3b3b3bULL;
        uint64_t sep=(x-0x0101010101010101ULL)&~x&0x8080808080808080ULL;
        if(sep) key &= (1ULL << __builtin_ctzll(sep))-1;
        unsigned slot=(key*HASH)>>(64-10);
        Station *s;
        while((s=map[slot])->key!=key || (s->ambiguous && p[8]!=names[s->idx][8])) slot=(slot+1)&(SLOTS-1);
        const char *t=p+s->len+1;
        int neg=*t=='-'; t+=neg;
        int v=*t++-'0';
        if(*t!='.') v=v*10+(*t++-'0');
        t++;
        v=v*10+(*t++-'0');
        t++; // newline
        p=t;
        if(neg) v=-v;
        Stats *a=&w->stats[s->idx];
        if(!a->count) a->min=a->max=v;
        else { if(v<a->min)a->min=v; if(v>a->max)a->max=v; }
        a->sum+=v; a->count++;
    }
    return NULL;
}
static void print_temp(int t) { if(t<0) { putchar('-'); t=-t; } printf("%d.%d",t/10,t%10); }
int main(int argc, char **argv) {
    if(argc!=2) return 1;
    int fd=open(argv[1],O_RDONLY); if(fd<0) { perror("open"); return 1; }
    struct stat st; if(fstat(fd,&st)) return 1;
    file_size=st.st_size;
    if(!file_size) { fputs("{}",stdout); return 0; }
    data=mmap(NULL,file_size,PROT_READ,MAP_PRIVATE,fd,0);
    if(data==MAP_FAILED) { perror("mmap"); return 1; }
    close(fd);
    init();
    workers=calloc(THREADS,sizeof(Worker));
    pthread_t threads[THREADS];
    const char *bounds[THREADS+1]; bounds[0]=data; bounds[THREADS]=data+file_size;
    for(int i=1;i<THREADS;i++) { const char *p=data+file_size*i/THREADS; while(*p!='\n') p++; bounds[i]=p+1; }
    for(int i=0;i<THREADS;i++) { workers[i].begin=bounds[i]; workers[i].end=bounds[i+1]; pthread_create(&threads[i],NULL,work,&workers[i]); }
    for(int i=0;i<THREADS;i++) pthread_join(threads[i],NULL);
    putchar('{'); int emitted=0;
    for(int j=0;j<N;j++) {
        int64_t sum=0; int count=0, mn=9999, mx=-9999;
        for(int i=0;i<THREADS;i++) {
            Stats *a=&workers[i].stats[j]; if(!a->count) continue;
            sum+=(int64_t)a->sum; count+=a->count;
            if(a->min<mn)mn=a->min; if(a->max>mx)mx=a->max;
        }
        if(!count)continue;
        if(emitted++)fputs(", ",stdout);
        fputs(names[j],stdout); putchar('='); print_temp(mn); putchar('/');
        int neg=sum<0; uint64_t ab=neg?-sum:sum;
        int mean=(int)((ab*2+count)/(2*(int64_t)count));
        print_temp(neg?-mean:mean); putchar('/'); print_temp(mx);
    }
    putchar('}');
    return 0;
}

