static unsigned char seen[8192];
int main(void) {
 uint64_t keys[412]; FILE *f=fopen("/work/prefix.bin","rb");
 for(int i=0;i<412;i++) fread(&keys[i],8,1,f);
 uint64_t alex=0; for(int i=0;i<8;i++)alex|=(uint64_t)(unsigned char)"Alexandr"[i] << (i*8);
 for(uint64_t c=0x9e3779b97f4a7c15ULL,trial=0;trial<100000000;trial++,c+=0x9e3779b97f4a7c15ULL) {
   unsigned char epoch=(trial%254)+1;
   if(epoch==1) for(int k=0;k<8192;k++)seen[k]=0;
   int k;
   for(k=0;k<412;k++) {
     unsigned slot=(keys[k]*c)>>51;
     if(seen[slot]==epoch)break;
     seen[slot]=epoch;
   }
   if(k==412 && seen[((alex*c)>>51)+1]!=epoch) { printf("%llu 0x%llx alex slot %u\n",(unsigned long long)trial,(unsigned long long)c,(unsigned)((alex*c)>>51)); return 0; }
 }
