#define _GNU_SOURCE
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include "stations.h"

#define N 413
#define SLOTS 8192
#define THREADS 4
#define HASH 0x3b63b30ee42484d9ULL
#define ALEX_SLOT 3499

typedef struct { const char *name; int64_t sum; uint32_t count; int16_t min,max; uint8_t len; } Entry;
typedef struct { Entry slots[SLOTS]; const char *begin,*end; } Worker;
static Worker *workers;
static unsigned indexes[N];
static const char *data;
static size_t file_size;
static void init(void) {
    for(int j=0;j<N;j++) {
        const char *name=names[j]; unsigned len=strlen(name);
        uint64_t key=0; memcpy(&key,name,len<8?len:8);
        unsigned idx=(key*HASH)>>51;
        if(idx==ALEX_SLOT && name[8]=='i')idx++;
        indexes[j]=idx;
        for(int i=0;i<THREADS;i++) {
            Entry *e=&workers[i].slots[idx];
            e->name=name; e->len=len;
        }
    }
}
static void *work(void *arg) {
    Worker *w=arg;
    const char *p=w->begin, *end=w->end;
    while(p<end) {
        uint64_t key; memcpy(&key,p,8);
        uint64_t x=key^0x3b3b3b3b3b3b3b3bULL;
        uint64_t semi=(x-0x0101010101010101ULL)&~x&0x8080808080808080ULL;
        if(semi) key &= (1ULL << (__builtin_ctzll(semi)&~7))-1;
        unsigned idx=(key*HASH)>>51;
        if(__builtin_expect(idx==ALEX_SLOT,0)) idx+=(p[8]=='i');
        Entry *v=&w->slots[idx];
        p+=v->len+1;
        int sign=1;
        if(*p=='-') { sign=-1; p++; }
        int t=*p++-'0';
        if(*p!='.') t=t*10+(*p++-'0');
        p++;
        t=t*10+(*p++-'0');
        t*=sign;
        p++;
        if(!v->count) { v->min=v->max=t; }
        else { if(t<v->min) v->min=t; if(t>v->max) v->max=t; }
        v->sum+=t; v->count++;
    }
    return NULL;
}
static void print_temp(int t) { if(t<0) { putchar('-'); t=-t; } printf("%d.%d",t/10,t%10); }
int main(int argc, char **argv) {
    if(argc!=2) return 1;
    int fd=open(argv[1],O_RDONLY); if(fd<0) { perror("open"); return 1; }
    struct stat st; if(fstat(fd,&st)) return 1;
    file_size=st.st_size;
    if(!file_size) { fputs("{}",stdout); return 0; }
    data=mmap(NULL,file_size,PROT_READ,MAP_PRIVATE,fd,0);
    if(data==MAP_FAILED) { perror("mmap"); return 1; }
    close(fd);
    workers=calloc(THREADS,sizeof(Worker));
    init();
    pthread_t threads[THREADS];
    const char *bounds[THREADS+1]; bounds[0]=data; bounds[THREADS]=data+file_size;
    for(int i=1;i<THREADS;i++) { const char *p=data+file_size*i/THREADS; while(*p!='\n') p++; bounds[i]=p+1; }
    for(int i=0;i<THREADS;i++) { workers[i].begin=bounds[i]; workers[i].end=bounds[i+1]; pthread_create(&threads[i],NULL,work,&workers[i]); }
    for(int i=0;i<THREADS;i++) pthread_join(threads[i],NULL);
    putchar('{'); int emitted=0;
    for(int j=0;j<N;j++) {
        int64_t sum=0; int count=0, mn=9999,mx=-9999;
        for(int i=0;i<THREADS;i++) {
            Entry *e=&workers[i].slots[indexes[j]]; if(!e->count) continue;
            sum+=e->sum; count+=e->count;
            if(e->min<mn) mn=e->min; if(e->max>mx)mx=e->max;
        }
        if(!count)continue;
        if(emitted++)fputs(", ",stdout);
        fputs(names[j],stdout); putchar('='); print_temp(mn); putchar('/');
        int neg=sum<0; uint64_t ab=neg?-sum:sum;
        int mean=(int)((ab*2+count)/(2*(int64_t)count));
        print_temp(neg?-mean:mean); putchar('/'); print_temp(mx);
    }
    putchar('}');
    return 0;
}

